#!/usr/bin/env bash
# Check that the kind API server audit log contains the events the Sigma rules in deploy/detections
# are written for. This is a hand translation of each rule's logic to jq over the raw JSON events;
# it proves the field paths and values are real, not that a SIEM backend is configured.
#
# Events are generated by deploy/scripts/netpol-test.sh (exec, privileged pod) and by this script
# (secret read with a token for a service account that is not kevgate's).
#
# Usage: audit-check.sh [OUT_DIR]   (writes OUT_DIR/kube-apiserver-audit.log)
set -euo pipefail

NS="${NS:-kevgate}"
NODE="${KIND_NODE:-kevgate-control-plane}"
OUT_DIR="${1:-${RUNNER_TEMP:-/tmp}/kevgate-audit}"
mkdir -p "${OUT_DIR}"
LOG="${OUT_DIR}/kube-apiserver-audit.log"

# Secret access attempt by the namespace's default SA (no RBAC, so 403; the attempt is the signal).
token="$(kubectl -n "${NS}" create token default --duration=10m)"
if kubectl --token="${token}" -n "${NS}" get secret kevgate-api-keys >/dev/null 2>&1; then
  echo "FAIL: default service account can read kevgate-api-keys"; exit 1
fi
echo "ok   default SA cannot read kevgate-api-keys (403)"
unset token

sleep 3   # let the audit backend flush
docker exec "${NODE}" cat /var/log/kubernetes/kube-apiserver-audit.log > "${LOG}"
echo "audit log: $(wc -l < "${LOG}") events"

check() { # name jq-filter
  local n
  n="$(jq -c "select($2)" "${LOG}" | wc -l)"
  if (( n > 0 )); then echo "ok   $1: ${n} matching event(s)"; else echo "FAIL $1: no matching events"; return 1; fi
}

rc=0
check "k8s_exec_into_kevgate_pod" '
  .objectRef.resource == "pods" and (.objectRef.subresource == "exec" or .objectRef.subresource == "attach")
  and .objectRef.namespace == "'"${NS}"'" and (.objectRef.name // "" | startswith("kevgate-"))' || rc=1

check "k8s_kevgate_secret_read_by_other_sa" '
  (.verb == "get" or .verb == "list" or .verb == "watch") and .objectRef.resource == "secrets"
  and .objectRef.namespace == "'"${NS}"'" and (.user.username | startswith("system:serviceaccount:"))
  and .user.username != "system:serviceaccount:'"${NS}"':kevgate"
  and (.user.username | startswith("system:serviceaccount:kube-system:") | not)' || rc=1

check "k8s_privileged_pod_in_kevgate_namespace" '
  .verb == "create" and .objectRef.resource == "pods" and .objectRef.namespace == "'"${NS}"'"
  and ([.requestObject.spec.containers[]?.securityContext.privileged] | any)' || rc=1

exit "${rc}"
